import type { PrismAnchors } from './prism'
import type { ThemeVariant } from './types'

/**
 * A theme is only a set of Prism anchors. Surfaces, borders, interaction
 * states and readable foregrounds are generated by Prism (ADR-0016).
 */
export type ThemeDefinition = {
  id: string
  anchors: Record<ThemeVariant, PrismAnchors>
}

